(() => {
  'use strict';
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let printState=[];
  window.addEventListener('beforeprint',()=>{printState=[...document.querySelectorAll('[data-reading-fold],.cycle-period')].map(x=>[x,x.open]);printState.forEach(([x])=>x.open=true);});
  window.addEventListener('afterprint',()=>{printState.forEach(([x,open])=>x.open=open);printState=[];});
  const elementClass=e=>({'목':'wood','화':'fire','토':'earth','금':'metal','수':'water'}[e]||'');
  const words={
    '일간':['일간 · 나를 읽는 기준','태어난 날의 천간이에요. 십성과 다른 글자 사이의 관계를 계산할 때 기준이 됩니다.'],
    '십성':['십성 · 역할과 관계의 분류','일간과 다른 글자의 오행·음양 관계를 열 가지로 나눈 전통 분류예요. 천간과 지지 본기를 구분해서 계산해요.'],
    '지장간':['지장간 · 지지 안의 천간','각 지지에 배정된 숨은 천간이에요. 여기·중기·본기로 나누며, 본기는 중심이 되는 천간입니다. 겉 글자 수에는 중복 합산하지 않아요.'],
    '십이운성':['십이운성 · 관계의 단계 이름','일간과 지지의 관계를 열두 단계로 구분한 전통 명칭이에요. 병·사·절이라는 글자를 실제 질병·죽음·수명으로 읽지 않아요.'],
    '용신':['용신 · 균형을 읽는 기준','계절과 일간의 강약 등을 고려하여 균형에 도움이 된다고 선택한 오행이에요. 조후는 계절의 한열·건습, 억부는 일간의 강약을 살피는 방식입니다. 오행 개수만으로 고르지 않아요.'],
    '신강·신약':['신강·신약 · 일간의 지지 관계','일간을 돕는 관계와 월지의 계절, 지지의 뿌리 등을 살피는 명리학 분류예요. 개인의 능력이나 건강의 강약을 뜻하지 않아요.'],
    '격국':['격국 · 월지를 중심으로 읽는 구조','월지의 지장간과 천간에 드러난 글자 등을 기준으로 정하는 전통 분류예요. 이 보고서는 계산한 격국 이름과 선택 근거를 함께 제시해요.']
  };
  const term=label=>`<button class="term-button" data-term="${escape(label)}">${escape(label)} <span aria-hidden="true">?</span></button>`;
  function pillarTable(r){
    const columns=['hour','day','month','year'].map(pos=>r.pillars.find(p=>p.position===pos));
    const cell=(p,part)=>p?.known?`<span class="hanja ${elementClass(p[part].element)}">${escape(p[part].hanja)}</span><span class="hanja-reading">${escape(p[part].hangul)} · ${escape(p[part].element)}</span>`:'<span class="unknown-pillar">미입력</span>';
    const row=(label,fn)=>`<tr><th scope="row">${label}</th>${columns.map(p=>`<td class="${p?.position==='day'?'day-column':''}">${p?.known?fn(p):'—'}</td>`).join('')}</tr>`;
    return `<div class="pillar-table-wrap"><table class="pillar-table"><caption class="visually-hidden">출생 정보로 계산한 사주 명식. 시주, 일주, 월주, 년주 순서.</caption><thead><tr><th scope="col">명식</th>${columns.map(p=>`<th scope="col" class="${p?.position==='day'?'day-column':''}">${escape(p?.label)}${p?.position==='day'?'<small>나의 기준</small>':''}</th>`).join('')}</tr></thead><tbody><tr class="character-row"><th scope="row">천간</th>${columns.map(p=>`<td class="${p?.position==='day'?'day-column':''}">${cell(p,'stem')}</td>`).join('')}</tr><tr class="character-row"><th scope="row">지지</th>${columns.map(p=>`<td class="${p?.position==='day'?'day-column':''}">${cell(p,'branch')}</td>`).join('')}</tr>${row('천간 십성',p=>escape(p.stem.ten_god))}${row('지지 십성',p=>escape(p.branch.ten_god))}${row('지장간',p=>p.hidden_stems.map(s=>`<span class="hidden-stem">${escape(s.hanja)}<small>${escape(s.role)}</small></span>`).join(''))}${row('십이운성',p=>escape(p.stage))}</tbody></table></div>`;
  }
  function balance(r){
    const b=r.balance;
    if(!b.available)return `<div class="missing-analysis"><h4>시간이 필요한 분석은 기다려둘게요.</h4><p>${escape(b.reason)} 시주를 임의로 채우지 않고 세 기둥의 구조를 살펴봤어요.</p></div>`;
    return `<div class="balance-grid"><article><span class="report-overline">일간의 지지 관계</span><h4>${escape(b.strength)}</h4><p>월지의 지지 ${b.month_supports?'있음':'없음'} · 일지의 지지 ${b.day_supports?'있음':'없음'}</p><small>득령·득지·인비 관계를 살피는 억부 분류</small></article><article><span class="report-overline">월지를 읽는 구조</span><h4>${escape(b.pattern)}</h4><p>${escape(b.pattern_basis)}</p><small>${b.pattern_established===false?'달의 관계를 참고한 분류 · 격의 성립과 구분':'계산 규칙에 따른 격국 분류'}</small></article><article><span class="report-overline">선택한 균형의 기준</span><h4>${escape(b.yong_element||'미선정')} <span>${escape(b.yong_method)}</span></h4><p>희신 ${escape(b.hee_element||'미선정')} · 계절 상태 ${escape(b.season_state)}</p><small>용신과 희신은 계산 규칙의 선택 결과</small></article></div><details class="method-detail"><summary>판단 방식과 보조 배점 확인하기 <span>+</span></summary><p>주된 표시는 <b>${escape(b.strength)}</b>, 계산 엔진의 보조 배점 결과는 <b>${escape(b.secondary_strength)}</b> (${escape(b.secondary_score)}/10)이에요. 두 방식의 가정이 달라 결과가 다를 수 있어요.</p><div class="weight-list">${Object.entries(b.secondary_components).map(([k,v])=>`<span>${escape(k)} <b>${escape(v)}</b></span>`).join('')}</div><p>${escape(b.secondary_note)}</p><p>${escape(b.method_note)}</p></details>`;
  }
  function chapters(r){
    const labels={overview:'사주 총평',disposition:'성격과 기질',charm:'강점과 재능',shadow:'약점과 주의할 점',work:'직업·적성',career:'관운 · 인정과 책임',money:'재물운',relationships:'애정운',family:'가족운',friends:'대인운',elements:'오행과 기운',balance:'균형과 보완',closing:'종합 풀이'};
    if(!r.chapters?.length)return r.generation&&r.primary_service==='stars'?'<p>입력한 출생 정보로 사주도 따로 읽을 수 있어요.</p><button class="button" data-additional-service="saju">사주 풀이도 읽어보기</button>':'<p role="status">계산한 사주를 바탕으로 자세한 풀이를 작성하고 있어요.</p>';
    const groups=[['나를 이해하기',['overview','disposition','charm','shadow']],['일과 돈',['work','career','money']],['사랑과 사람',['relationships','family','friends']],['기운과 인생의 흐름',['elements','balance','closing']]];
    const outline=`<nav class="reading-outline" aria-label="궁금한 풀이로 이동">${groups.map(([label,topics],i)=>`<section class="reading-outline-group"><h4>0${i+1} · ${label}</h4><div>${topics.filter(t=>r.chapters.some(c=>c.topic===t)).map(t=>`<button data-chapter="chapter-${t}">${labels[t]}</button>`).join('')}${i===3?'<button data-chapter="chapter-life">인생의 계절</button>':''}</div></section>`).join('')}</nav>`;
    const frame=`<p class="birth-frame">${escape(r.interpretation_frame?.description||'출생 당시의 사주 구성을 읽는 풀이예요.')}</p>`;
    return frame+'<p class="fold-help">제목을 누르면 자세한 풀이가 펼쳐져요. 어려운 글자는 계산 근거에서 볼 수 있어요.</p>'+(r.input_basis?.comparison?.changes_pillars?'<p class="time-boundary-note">시간 보정 방식에 따라 일주나 시주가 달라질 수 있어요. 이 본문은 경도 보정 기준이며, 계산 근거에서 다른 방식의 글자를 비교할 수 있어요.</p>':'')+`<details class="reading-jump"><summary>궁금한 이야기 먼저 보기 <span>${r.chapters.length}가지 풀이</span></summary>${outline}</details>`+r.chapters.map(c=>`<details class="reading-chapter reading-fold" data-reading-fold id="chapter-${c.topic}" ${c.topic==='overview'?'open':''}><summary><span class="report-overline">${labels[c.topic]}</span><h3>${escape(c.title)}</h3><span class="fold-mark" aria-hidden="true">+</span></summary><div class="chapter-content">${c.differences?`<div class="chart-differences" aria-label="이 명식에서 다르게 읽은 조건">${c.differences.map(d=>`<div><span>${escape(d.label)}</span><strong>${escape(d.text)}</strong>${d.basis?`<small>${escape(d.basis)}</small>`:''}</div>`).join('')}</div>`:''}${c.topic==='shadow'&&r.review_points?.length?`<div class="individual-risk-points">${r.review_points.map(x=>`<article><h4>${escape(x.title)}</h4><p>${escape(x.text)}</p><details class="chapter-evidence"><summary>이 주의점의 근거</summary><p>${escape(x.basis)}</p></details></article>`).join('')}</div>`:''}${(c.paragraphs||[c.body]).map((p,i)=>`${c.paragraph_labels?.[i]?`<h4 class="reading-subheading">${escape(c.paragraph_labels[i])}</h4>`:''}<p class="chapter-body">${escape(p)}</p>`).join('')}<div class="reflection"><span>풀이의 핵심</span><p>${escape(c.reflection)}</p></div><details class="chapter-evidence"><summary>이 풀이의 근거 보기 <span>+</span></summary>${c.evidence_ids.map(id=>r.evidence.find(e=>e.id===id)).filter(Boolean).map(e=>`<p><b>${escape(e.label)}</b>${escape(e.text)}</p>`).join('')}<p>출생 정보로 계산한 글자의 관계를 전통적인 관점으로 풀었어요. 글자 수만으로 강약을 정하거나 현재의 상황을 추측하지 않습니다.</p></details></div></details>`).join('')+lifeStages(r)+`<p class="reading-notice">이 풀이의 기준은 입력한 출생 정보예요. 다른 날짜에 다시 읽어도 같은 원국과 해석 규칙을 사용합니다.</p>`;
  }
  function lifeStages(r){
    const c=r.luck_cycles;
    if(!c)return '';
    if(!c.available)return `<section class="life-section" id="chapter-life"><span class="report-overline">인생의 계절</span><h3>나이대마다 달라지는 이야기</h3><p class="chapter-body">${escape(c.reason)}</p><p class="report-footnote">위의 정보 수정에서 입력할 수 있어요. 이름으로 계산 기준을 추측하거나 모르는 시간을 채우지 않아요.</p></section>`;
    return `<section class="life-section" id="chapter-life"><span class="report-overline">인생의 계절 · 10년 대운</span><h3>시간이 흐르면,<br>내 이야기의 어디가 달라질까?</h3><p class="chapter-body">타고난 사주는 같아도, 10년마다 만나는 글자는 달라져요. 첫 대운은 <b>${escape(c.start_label)}</b> 무렵부터 이어집니다. 아래 나이는 출생 후 경과한 나이예요.</p><div class="life-stages">${c.stages.map((s,i)=>`<article class="life-stage"><div class="life-stage-head"><span class="stage-number" aria-hidden="true">0${i+1}</span><div><h4>${escape(s.label)}</h4><span>${escape(s.age_label)}</span></div></div>${s.title?`<h5 class="reading-subheading">${escape(s.title)}</h5>`:''}${s.period_labels?`<p class="report-footnote">${s.period_labels.map(escape).join(' · ')}</p>`:''}${s.paragraphs.length?s.paragraphs.map(p=>`<p class="chapter-body">${escape(p)}</p>`).join(''):'<p class="chapter-body" role="status">이 시기의 자세한 해설을 작성하고 있어요.</p>'}</article>`).join('')}</div><h4 class="cycle-heading">시기별 계산 근거 펼쳐보기</h4><div class="cycle-list">${c.periods.map(p=>`<details class="cycle-period"><summary><span class="cycle-age">${escape(p.age_label)}</span><span class="cycle-subtitle">${escape(p.reading)} · 계산표</span><span class="cycle-plus" aria-hidden="true">+</span></summary><div class="cycle-body">${p.paragraphs.map(x=>`<p class="chapter-body">${escape(x)}</p>`).join('')}${p.transition?`<p class="cycle-transition">${escape(p.transition)}</p>`:''}<details class="chapter-evidence"><summary>이 시기의 계산 근거</summary><p>${escape(p.calculation_text)}</p></details></div></details>`).join('')}</div><details class="chapter-evidence"><summary>대운의 계산 기준 보기 <span>+</span></summary><p>${escape(c.method)}</p><p>선택한 기준: ${c.criterion==='male'?'남성':'여성'} · 연간: ${escape(c.year_stem_polarity)} · 절기까지 ${escape(c.days_to_boundary)}일</p><p>${escape(c.scope)}</p></details></section>`;
  }
  function timeComparison(comparison){
    if(!comparison)return '';
    return `<details class="time-comparison"><summary>시간 보정에 따른 명식 비교</summary>${comparison.options.map(o=>`<p><b>${escape(o.label)}</b><br>${escape(o.date)} ${escape(o.time)} · 일주 ${escape(o.day)} · 시주 ${escape(o.hour)}</p>`).join('')}<small>${escape(comparison.note)}</small></details>`;
  }
  function render(r){
    return `<section class="professional-report"><div class="report-context"><p>${escape(r.profile.birth_date)} · ${escape(r.profile.birth_time||'시간 미입력')} · ${escape(r.profile.city)}</p></div><div class="report-nav" role="tablist" aria-label="통합 출생 리포트 보기"><button id="tab-interpretation" role="tab" aria-controls="panel-interpretation" aria-selected="true" data-report-tab="interpretation">사주 풀이</button><button id="tab-calculation" role="tab" aria-controls="panel-calculation" aria-selected="false" tabindex="-1" data-report-tab="calculation">계산 근거</button><button id="tab-astrology" role="tab" aria-controls="panel-astrology" aria-selected="false" tabindex="-1" data-report-tab="astrology">별자리</button><button id="tab-name" role="tab" aria-controls="panel-name" aria-selected="false" tabindex="-1" data-report-tab="name">이름</button></div><div id="panel-interpretation" role="tabpanel" aria-labelledby="tab-interpretation">${chapters(r)}</div><div id="panel-calculation" role="tabpanel" aria-labelledby="tab-calculation" hidden>${window.MoaProfile.overview(r)}<section class="report-section"><div class="report-section-heading"><div><h3>나의 사주 명식</h3></div>${term('일간')}</div><p class="report-description">절기 월과 출생지 경도를 적용한 명식이에요. 일주가 다른 글자를 읽는 기준이 됩니다.</p>${pillarTable(r)}${r.input_basis?`<div class="calculation-input-basis"><p><b>다른 사주와 비교할 입력 기준</b><br>${escape(r.input_basis.calendar)} · ${escape(r.input_basis.timezone)}${r.input_basis.entered_time?`<br>입력 시각 ${escape(r.input_basis.entered_time)} → 경도 보정 시각 ${escape(r.input_basis.corrected_time)}`:' · 출생 시간 미입력'}</p><small>${escape(r.input_basis.note)}<br>${escape(r.input_basis.coordinate_basis||'')} · ${escape(r.profile.city)} · 경도 ${escape(r.input_basis.longitude)}°</small>${timeComparison(r.input_basis.comparison)}</div>`:''}<div class="term-links">${['십성','지장간','십이운성'].map(term).join('')}</div><p class="report-footnote">지지 십성은 본기 기준이에요. 십이운성의 병·사·절은 전통 단계 명칭입니다.</p></section><section class="report-section"><div class="report-section-heading"><div><h3>오행의 구성</h3></div><span class="count-caption">겉 글자 ${r.element_total}개</span></div><div class="elements-layout"><div class="element-bars">${r.elements.map(e=>`<div class="element-row"><span class="element-label"><i class="${elementClass(e.element)}"></i>${escape(e.label)}</span><div class="element-track" role="meter" aria-label="${escape(e.label)} 개수" aria-valuenow="${e.count}" aria-valuemin="0" aria-valuemax="${r.element_total}"><span class="${elementClass(e.element)}" style="width:${Math.max(0,Math.min(100,e.percent))}%"></span></div><b>${e.count}</b><small>${e.percent}%</small></div>`).join('')}</div><aside class="element-aside"><span>${escape(r.month.hanja)}月</span><h4>${escape(r.month.season)}의 절기 월</h4><p>겉 글자의 개수와 계절의 영향은 구분해서 읽어요. 적게 보이는 오행을 곧바로 용신으로 고르지 않아요.</p></aside></div><p class="report-footnote">분포는 천간·지지 본래 오행의 단순 개수예요. 지장간이나 계절 가중치를 포함한 강약 점수가 아닙니다.</p></section><section class="report-section"><div class="report-section-heading"><div><h3>십성으로 읽는 역할</h3></div>${term('십성')}</div><div class="ten-god-grid">${r.ten_gods.map(g=>`<article><div><h4>${escape(g.name)}</h4><span>${g.count}자리</span></div><strong>${escape(g.keyword)}</strong><p>${escape(g.explanation)}</p></article>`).join('')}</div><p class="report-footnote">일간을 제외한 천간과 지지 본기에서 집계했어요. 지장간은 중복 집계하지 않았어요.</p></section><section class="report-section"><div class="report-section-heading"><div><h3>강약·격국과 용신</h3></div>${term('용신')}</div>${balance(r)}<div class="term-links">${term('신강·신약')}${term('격국')}</div></section><section class="report-section"><div class="report-section-heading"><div><h3>명식 안의 글자 관계</h3></div></div><div class="relation-list">${r.relations.length?r.relations.map(v=>`<div><span>${escape(v.kind)}</span><b>${escape(v.members)}</b><small>관계표에서 검출</small></div>`).join(''):'<p>이 관계표에서 검출한 합·충·형·파·해가 없어요.</p>'}</div><p class="report-footnote">관계의 검출과 실제 합화의 성립은 구분해요. 관계 명칭 하나로 사건이나 삶의 결과를 정하지 않아요.</p></section><div class="coverage-note"><span>분석 범위</span><p>${escape(r.scope)}</p></div></div><div id="panel-astrology" role="tabpanel" aria-labelledby="tab-astrology" hidden>${window.MoaProfile.astrology(r)}</div><div id="panel-name" role="tabpanel" aria-labelledby="tab-name" hidden>${window.MoaProfile.name(r)}</div></section>`;
  }
  function mount(root,onTerm){
    root.querySelectorAll('[data-chapter]').forEach(b=>b.addEventListener('click',()=>(()=>{const target=root.querySelector('#'+b.dataset.chapter);if(target){target.open=true;target.scrollIntoView({block:'start',behavior:'auto'});}})()));
    const tabs=[...root.querySelectorAll('[data-report-tab]')];
    function select(target){tabs.forEach(b=>{const active=b===target;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;root.querySelector('#panel-'+b.dataset.reportTab).hidden=!active;});}
    tabs.forEach((b,i)=>{b.addEventListener('click',()=>select(b));b.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;select(tabs[index]);tabs[index].focus();});});
    root.querySelectorAll('[data-term]').forEach(b=>b.addEventListener('click',()=>{const [title,text]=words[b.dataset.term];onTerm(title,`<p>${escape(text)}</p>`);}));
  }
  window.MoaReport={render,mount};
})();
